import { NavLink, Outlet, useNavigate } from "react-router-dom";
import { useEffect, useRef, useState } from "react";
import {
  LayoutDashboard, Search, ClipboardList,
  ShieldAlert, Store as StoreIcon, Settings, Bell, ChefHat,
  Sparkles, Command, ChevronRight, AlertTriangle, CheckCircle2, LogOut,
} from "lucide-react";
import { useStore } from "@/store/useStore";
import { ToastContainer, toast } from "@/components/Toast";
import CommandPalette from "@/components/CommandPalette";
import { cn } from "@/lib/utils";

const menuItems = [
  { path: "/", label: "首页", icon: LayoutDashboard, desc: "产品概览" },
  { path: "/inspection", label: "巡检管理", icon: Search, desc: "巡检记录" },
  { path: "/template", label: "巡检模板", icon: ClipboardList, desc: "标准模板" },
  { path: "/risk", label: "风险中心", icon: ShieldAlert, desc: "整改闭环" },
  { path: "/store", label: "门店管理", icon: StoreIcon, desc: "50家门店" },
  { path: "/settings", label: "系统设置", icon: Settings, desc: "账号配置" },
];

type NotifColor = "red" | "amber" | "emerald";

const notifications: {
  id: number;
  icon: typeof ShieldAlert;
  title: string;
  desc: string;
  time: string;
  color: NotifColor;
}[] = [
  { id: 1, icon: ShieldAlert, title: "上海浦东店发现高风险项", desc: "操作台卫生不达标 · 2项严重", time: "5分钟前", color: "red" },
  { id: 2, icon: AlertTriangle, title: "操作台卫生待整改", desc: "北京三里屯店 · 逾期未处理", time: "32分钟前", color: "amber" },
  { id: 3, icon: AlertTriangle, title: "冷藏温度异常告警", desc: "广州天河店 · 冷藏柜温度 12°C", time: "1小时前", color: "amber" },
  { id: 4, icon: CheckCircle2, title: "杭州西湖店已整改完成", desc: "消毒记录补录 · 已复核通过", time: "3小时前", color: "emerald" },
];

const NOTIF_COLOR: Record<NotifColor, string> = {
  red: "bg-red-50 text-red-500",
  amber: "bg-amber-50 text-amber-500",
  emerald: "bg-emerald-50 text-emerald-500",
};

export default function Layout() {
  const navigate = useNavigate();
  const user = useStore((s) => s.currentUser);
  const initRisks = useStore((s) => s.initRisks);
  const resetData = useStore((s) => s.resetData);

  // 下拉面板 open/close 状态
  const [notifOpen, setNotifOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  // 应用初始化时确保风险数据已加载
  useEffect(() => {
    initRisks();
  }, [initRisks]);

  // 点击外部关闭下拉面板
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as Node;
      if (notifRef.current && !notifRef.current.contains(target)) {
        setNotifOpen(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(target)) {
        setUserMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const openCommandPalette = () => {
    window.dispatchEvent(new CustomEvent("open-command-palette"));
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {/* === 侧栏：深色品牌色 + 玻璃感 === */}
      <aside className="w-60 flex flex-col flex-shrink-0 relative overflow-hidden bg-gradient-to-b from-ink-900 via-ink-900 to-ink-950">
        {/* 顶部光晕装饰 */}
        <div className="absolute top-0 left-0 right-0 h-40 bg-gradient-to-b from-brand-900/40 to-transparent pointer-events-none" />
        <div className="absolute -top-20 -right-20 w-60 h-60 rounded-full bg-brand-700/20 blur-3xl pointer-events-none" />
        <div className="absolute top-1/2 -left-20 w-40 h-40 rounded-full bg-cyan-600/10 blur-3xl pointer-events-none" />

        {/* Logo */}
        <div className="h-16 flex items-center gap-3 px-5 relative z-10">
          <div className="relative">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-brand-500 via-brand-700 to-cyan-600 flex items-center justify-center shadow-glow-brand">
              <ChefHat className="w-5 h-5 text-white" />
            </div>
            <div className="absolute -top-0.5 -right-0.5 w-2.5 h-2.5 rounded-full bg-emerald-400 border-2 border-ink-900 shadow-[0_0_8px_rgba(16,185,129,0.6)]" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5">
              <span className="text-base font-bold text-white tracking-tight">后厨哨兵</span>
              <span className="px-1.5 py-0.5 text-[9px] font-bold rounded bg-gradient-to-r from-cyan-500 to-brand-500 text-white">PRO</span>
            </div>
            <p className="text-[10px] text-ink-400 tracking-wider uppercase -mt-0.5">Kitchen Sentry · AI</p>
          </div>
        </div>

        {/* 菜单 */}
        <nav className="flex-1 py-3 px-3 space-y-0.5 overflow-y-auto relative z-10">
          <p className="px-3 py-2 text-[10px] font-semibold text-ink-500 tracking-widest uppercase">
            Navigation
          </p>
          {menuItems.map((item) => {
            const Icon = item.icon;
            return (
              <NavLink
                key={item.path}
                to={item.path}
                end={item.path === "/"}
                className={({ isActive }) =>
                  cn(
                    "group relative flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm transition-all duration-200",
                    isActive
                      ? "bg-gradient-to-r from-brand-700/80 to-brand-800/40 text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.1)]"
                      : "text-ink-400 hover:text-white hover:bg-white/5"
                  )
                }
              >
                {({ isActive }) => (
                  <>
                    {isActive && (
                      <span className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-5 rounded-r-full bg-gradient-to-b from-cyan-400 to-brand-500 shadow-[0_0_8px_rgba(6,182,212,0.6)]" />
                    )}
                    <Icon
                      className={cn(
                        "w-4 h-4 flex-shrink-0 transition-colors",
                        isActive ? "text-cyan-300" : "text-ink-400 group-hover:text-ink-200"
                      )}
                    />
                    <span className="flex-1 font-medium">{item.label}</span>
                    {isActive && <ChevronRight className="w-3.5 h-3.5 text-ink-400" />}
                  </>
                )}
              </NavLink>
            );
          })}
        </nav>

        {/* AI 状态卡 */}
        <div className="mx-3 mb-3 relative z-10">
          <div className="relative rounded-xl p-3 bg-gradient-to-br from-brand-800/60 to-ink-800/80 border border-white/10 overflow-hidden">
            <div className="absolute -top-8 -right-8 w-20 h-20 rounded-full bg-cyan-500/20 blur-2xl" />
            <div className="relative flex items-center gap-2 mb-1">
              <Sparkles className="w-3.5 h-3.5 text-cyan-300" />
              <span className="text-xs font-semibold text-white">AI 模型</span>
              <span className="ml-auto flex items-center gap-1 text-[10px] text-emerald-400">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 shadow-[0_0_6px_rgba(16,185,129,0.8)]" />
                在线
              </span>
            </div>
            <p className="text-[11px] text-ink-300 leading-relaxed">v2.1 · GPT-4V 视觉识别</p>
          </div>
        </div>

        {/* 用户卡 */}
        <div className="p-3 border-t border-white/5 relative z-10">
          <div className="flex items-center gap-2.5 px-2 py-2 rounded-lg hover:bg-white/5 transition cursor-pointer">
            <div className="relative">
              <div className="w-9 h-9 rounded-full bg-gradient-to-br from-cyan-500 to-brand-700 flex items-center justify-center text-white font-semibold text-sm">
                {user.avatar}
              </div>
              <span className="absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full bg-emerald-400 border-2 border-ink-900" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-white truncate">{user.name}</p>
              <p className="text-[10px] text-ink-400">{user.role}</p>
            </div>
          </div>
        </div>
      </aside>

      {/* === 主区域 === */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* 顶栏 */}
        <header className="h-16 glass border-b border-ink-200/60 flex items-center justify-between px-7 flex-shrink-0 relative z-10">
          <div className="flex items-center gap-2 text-sm">
            <Sparkles className="w-4 h-4 text-brand-700" />
            <span className="text-gradient font-semibold">茶小鲜</span>
            <span className="text-ink-300">/</span>
            <span className="text-ink-600 font-medium">品控管理平台</span>
            <span className="ml-2 px-2 py-0.5 text-[10px] font-semibold rounded-full bg-gradient-to-r from-brand-900 to-cyan-600 text-white">
              50 门店
            </span>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={openCommandPalette}
              className="hidden md:flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-ink-100/80 text-[11px] text-ink-500 font-mono hover:bg-ink-200/80 hover:text-ink-700 transition cursor-pointer"
            >
              <Command className="w-3 h-3" />
              <span>K</span>
              <span className="text-ink-400">·</span>
              <span>搜索</span>
            </button>

            {/* 铃铛通知 */}
            <div className="relative" ref={notifRef}>
              <button
                onClick={() => setNotifOpen((v) => !v)}
                className={cn(
                  "relative w-9 h-9 rounded-lg flex items-center justify-center transition",
                  notifOpen ? "bg-ink-100" : "hover:bg-ink-100/80"
                )}
              >
                <Bell className={cn("w-4 h-4 transition-colors", notifOpen ? "text-brand-700" : "text-ink-600")} />
                <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full shadow-[0_0_6px_rgba(239,68,68,0.6)]">
                  <span className="absolute inset-0 rounded-full bg-red-500 animate-ping opacity-75" />
                </span>
              </button>
              {notifOpen && (
                <div className="absolute right-0 top-11 w-80 bg-white rounded-xl shadow-elevated border border-ink-200/80 overflow-hidden z-50 animate-fade-in-up">
                  <div className="flex items-center justify-between px-4 py-3 border-b border-ink-100 bg-gradient-to-r from-brand-50/50 to-cyan-50/30">
                    <div className="flex items-center gap-2">
                      <Bell className="w-4 h-4 text-brand-700" />
                      <span className="text-sm font-semibold text-ink-800">风险通知</span>
                    </div>
                    <span className="px-1.5 py-0.5 text-[10px] font-semibold rounded-full bg-red-100 text-red-600">
                      {notifications.length} 新
                    </span>
                  </div>
                  <div className="max-h-80 overflow-y-auto thin-scroll">
                    {notifications.map((n) => {
                      const Icon = n.icon;
                      return (
                        <button
                          key={n.id}
                          onClick={() => {
                            setNotifOpen(false);
                            navigate("/risk");
                          }}
                          className="w-full flex items-start gap-3 px-4 py-3 hover:bg-ink-50/80 transition text-left border-b border-ink-50 last:border-b-0 cursor-pointer"
                        >
                          <div className={cn("w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0", NOTIF_COLOR[n.color])}>
                            <Icon className="w-4 h-4" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium text-ink-800 truncate">{n.title}</p>
                            <p className="text-[11px] text-ink-400 mt-0.5 truncate">{n.desc}</p>
                            <p className="text-[10px] text-ink-300 mt-1">{n.time}</p>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                  <button
                    onClick={() => {
                      setNotifOpen(false);
                      navigate("/risk");
                    }}
                    className="w-full px-4 py-2.5 text-center text-xs font-medium text-brand-700 hover:bg-brand-50/50 transition border-t border-ink-100 cursor-pointer"
                  >
                    查看全部风险 →
                  </button>
                </div>
              )}
            </div>

            {/* 用户菜单 */}
            <div className="relative" ref={userMenuRef}>
              <div
                onClick={() => setUserMenuOpen((v) => !v)}
                className={cn(
                  "flex items-center gap-2 pl-3 pr-1 py-1 rounded-lg transition cursor-pointer",
                  userMenuOpen ? "bg-ink-100" : "hover:bg-ink-100/80"
                )}
              >
                <span className="text-sm text-ink-700 font-medium">{user.name}</span>
                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-cyan-500 to-brand-700 flex items-center justify-center text-white font-semibold text-xs">
                  {user.avatar}
                </div>
              </div>
              {userMenuOpen && (
                <div className="absolute right-0 top-11 w-48 bg-white rounded-xl shadow-elevated border border-ink-200/80 overflow-hidden z-50 animate-fade-in-up">
                  <div className="px-4 py-2.5 border-b border-ink-100 bg-ink-50/40">
                    <p className="text-sm font-semibold text-ink-800 truncate">{user.name}</p>
                    <p className="text-[11px] text-ink-400">{user.role}</p>
                  </div>
                  <div className="py-1">
                    <button
                      onClick={() => {
                        setUserMenuOpen(false);
                        navigate("/settings");
                      }}
                      className="w-full flex items-center gap-2.5 px-4 py-2 text-sm text-ink-700 hover:bg-ink-50/80 transition cursor-pointer"
                    >
                      <Settings className="w-4 h-4 text-ink-500" />
                      <span>系统设置</span>
                    </button>
                    <button
                      onClick={() => {
                        resetData();
                        setUserMenuOpen(false);
                        toast({ type: "success", title: "演示数据已重置", message: "所有数据已恢复到初始状态" });
                      }}
                      className="w-full flex items-center gap-2.5 px-4 py-2 text-sm text-ink-700 hover:bg-ink-50/80 transition cursor-pointer"
                    >
                      <Sparkles className="w-4 h-4 text-ink-500" />
                      <span>重置演示数据</span>
                    </button>
                    <button
                      onClick={() => {
                        setUserMenuOpen(false);
                        toast({ type: "info", title: "已退出登录", message: "演示模式 · 不会真正退出" });
                      }}
                      className="w-full flex items-center gap-2.5 px-4 py-2 text-sm text-ink-700 hover:bg-ink-50/80 transition cursor-pointer"
                    >
                      <LogOut className="w-4 h-4 text-ink-500" />
                      <span>退出登录</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        {/* 内容区 */}
        <main className="flex-1 overflow-y-auto">
          <div className="max-w-[1600px] mx-auto px-7 py-6">
            <Outlet />
          </div>
        </main>
      </div>

      <ToastContainer />
      <CommandPalette />
    </div>
  );
}
