import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { Risk, RiskStatus, Inspection, Evidence, Grade, Store, RectificationTask, AuditEvent, RiskLevel } from "@/types";
import { getAllRisks } from "@/mock/inspections";
import { toast } from "@/components/Toast";
import type { Template } from "@/types";

export interface AppState {
  sidebarCollapsed: boolean;
  toggleSidebar: () => void;
  currentUser: { name: string; role: string; avatar: string };
  updateUser: (user: Partial<{ name: string; role: string; avatar: string }>) => void;

  // 业务数据
  risks: Risk[];
  extraInspections: Inspection[]; // 用户新建的巡检
  extraEvidences: Evidence[]; // 用户新建巡检的取证实体
  extraStores: Store[]; // 用户新建的门店
  rectificationTasks: RectificationTask[]; // 整改任务
  auditEvents: AuditEvent[]; // 审计事件

  // 风险操作
  updateRiskStatus: (riskId: string, status: RiskStatus) => void;
  initRisks: () => void;

  // 整改闭环操作
  confirmRisk: (riskId: string, params: { level?: RiskLevel; description?: string }) => void;
  startRectification: (riskId: string, params: { assignee: string; dueDate: string }) => void;
  submitRectification: (riskId: string, params: { fixNote: string; fixedPhotoUrl: string }) => void;
  verifyRectification: (riskId: string) => void;
  rejectRectification: (riskId: string, params: { rejectReason: string }) => void;

  // 新建巡检
  addInspection: (params: {
    storeId: string;
    template: Template;
    inspector: string;
    evidences: Evidence[];
  }) => string;

  // 新建门店
  addStore: (params: {
    name: string;
    region: string;
    address: string;
    manager: string;
    phone: string;
  }) => string;

  // 重置
  resetData: () => void;
}

const STATUS_LABEL: Record<RiskStatus, string> = {
  ai_detected: "AI识别",
  pending: "待确认",
  confirmed: "待整改",
  fixing: "整改中",
  fixed: "已整改",
  verified: "已验证",
};

function calcGrade(score: number): Grade {
  if (score >= 90) return "优";
  if (score >= 75) return "良";
  if (score >= 60) return "中";
  return "差";
}

// 本地时间字符串（避免 UTC 偏移）
function nowLocal(): string {
  const n = new Date();
  const p = (x: number) => String(x).padStart(2, "0");
  return `${n.getFullYear()}-${p(n.getMonth() + 1)}-${p(n.getDate())} ${p(n.getHours())}:${p(n.getMinutes())}:${p(n.getSeconds())}`;
}

// 整改后样本图库（确定性选择，避免每次刷新变化）
const FIXED_PHOTO_POOL = [
  "https://images.unsplash.com/photo-1583947581924-860bda6a26df?w=800&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1556910103-1c02745aae4d?w=800&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1581579438747-104c53e7cb71?w=800&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1604908554049-1dc9b8c1d939?w=800&auto=format&fit=crop",
];

function pickFixedPhoto(riskId: string): string {
  // 基于 riskId 稳定选择
  let h = 0;
  for (let i = 0; i < riskId.length; i++) {
    h = (h * 31 + riskId.charCodeAt(i)) >>> 0;
  }
  return FIXED_PHOTO_POOL[h % FIXED_PHOTO_POOL.length];
}

// 根据模板检查项和用户取证实体生成风险
// 按检查项分组 Evidence，每个检查项最多生成一条演示风险
// 部分检查项判定为"符合"，不生成风险
// 导出用于单元测试
export function generateRisksFromEvidences(
  inspectionId: string,
  template: Template,
  evidences: Evidence[]
): Risk[] {
  const risks: Risk[] = [];

  // 风险描述模板（按 category）
  const riskTemplates: Record<string, { desc: string; basis: string; suggestion: string }> = {
    食材标签: {
      desc: "鲜奶已过期3天，仍在冰箱存放未处理",
      basis: "《食品安全法》第三十四条 禁止生产经营超过保质期的食品",
      suggestion: "立即废弃过期食材，排查同批次产品，加强效期管理",
    },
    冰箱温度: {
      desc: "冷藏冰箱温度7.2℃，超出标准（0-4℃）3.2℃",
      basis: "GB 31605-2015 食品冷链物流温度控制要求",
      suggestion: "检查冰箱密封条和制冷系统，调整温度设定，记录维修",
    },
    操作台: {
      desc: "操作台生熟食材混放，存在交叉污染风险",
      basis: "餐饮服务食品安全操作规范 生熟分开要求",
      suggestion: "立即分开存放，使用专用容器和刀具，加强员工培训",
    },
    台账记录: {
      desc: "消毒台账缺失近3日记录，台账不连续",
      basis: "《食品安全法》第五十三条 进货查验记录制度",
      suggestion: "补充缺失记录，建立每日提醒机制，指定专人负责",
    },
    垃圾桶: {
      desc: "垃圾桶未加盖，周边有垃圾溢出",
      basis: "餐饮服务食品安全操作规范 废弃物管理要求",
      suggestion: "更换带盖垃圾桶，加强清理频次，设置分类标识",
    },
    消毒柜: {
      desc: "消毒柜指示灯异常，疑似设备故障",
      basis: "GB 14934-2016 消毒餐（饮）具标准",
      suggestion: "联系维修，暂停使用故障设备，启用备用消毒方案",
    },
    仓储: {
      desc: "仓库部分原料未离墙离地存放",
      basis: "餐饮服务食品安全操作规范 贮存要求 原料离墙离地10cm",
      suggestion: "增设货架托盘，确保所有原料离墙离地10cm以上",
    },
    洗手池: {
      desc: "洗手池洗手液不足，需及时补充",
      basis: "餐饮服务食品安全操作规范 从业人员卫生要求",
      suggestion: "及时补充洗手液，建立每日检查制度",
    },
    健康证: {
      desc: "2名员工健康证已过期，仍在岗操作",
      basis: "《食品安全法》第四十五条 从业人员健康管理制度",
      suggestion: "立即安排健康体检，过期员工暂停接触食品岗位",
    },
  };

  // 按模板类型决定哪些检查项生成风险（确定性，避免每次分析结果不同）
  // 索引模式：true = 生成风险，false = 判定符合
  const riskItemIndexPatterns: Record<string, boolean[]> = {
    daily: [true, true, true, false, false], // 前3项有风险
    standard: [true, true, true, true, true, false, false, false, false, false, false, false], // 前5项有风险
    special: [true, true, true, false, false, false], // 前3项有风险
  };
  const riskPattern = riskItemIndexPatterns[template.type] || [];

  // 风险等级分配（按检查项顺序，确定性）
  const levelPatterns: Record<string, ("high" | "mid" | "low")[]> = {
    daily: ["high", "mid", "low"],
    standard: ["high", "high", "mid", "mid", "low"],
    special: ["high", "mid", "low"],
  };
  const levels = levelPatterns[template.type] || ["mid", "low", "low"];

  let riskIdx = 0;

  // 遍历模板检查项，按检查项生成风险
  template.items.forEach((item, itemIdx) => {
    // 该检查项的所有 Evidence
    const itemEvidences = evidences.filter((e) => e.templateItemId === item.id);
    if (itemEvidences.length === 0) return; // 无证据，跳过

    // 根据模式决定是否生成风险
    const shouldGenerateRisk = riskPattern[itemIdx] ?? false;
    if (!shouldGenerateRisk) return; // 判定符合，不生成风险

    const level = levels[riskIdx] || "low";
    const category = item.category;
    const tpl = riskTemplates[category] || riskTemplates["操作台"];
    const riskId = `rk-new-${inspectionId}-${riskIdx}`;
    const evidenceIds = itemEvidences.map((e) => e.id);
    const primaryEvidence = itemEvidences[0];

    risks.push({
      id: riskId,
      inspectionId,
      description: tpl.desc,
      level,
      basis: tpl.basis,
      confidence: primaryEvidence.confidence,
      suggestion: tpl.suggestion,
      status: "ai_detected",
      photoId: primaryEvidence.id, // 主证据 ID（向后兼容）
      category,
      templateItemId: item.id,
      evidenceIds,
      primaryEvidenceId: primaryEvidence.id,
    });

    riskIdx++;
  });

  return risks;
}

// 数据迁移函数（导出用于单元测试）
// v1 → v2: extraPhotos 已废弃，改为 extraEvidences
// v2 → v3: 模板检查项增加结构化字段，Risk 关联方式变更，旧用户巡检/风险/evidence 全部清空
// v3 → v4: 新增整改闭环（rectificationTasks + auditEvents），旧 risks 状态可能不一致，清空旧 risks 重新加载
export function migrateStore(persisted: unknown, version: number): AppState {
  const s = (persisted || {}) as Record<string, unknown>;
  if (version < 3) {
    // 旧版数据结构不兼容，清空所有用户创建的数据
    delete s.extraPhotos;
    s.extraEvidences = [];
    s.extraInspections = [];
    s.extraStores = [];
    // risks 会在 initRisks 中从 Mock 重新加载
    s.risks = [];
    // 显示升级提示（通过 sessionStorage 标记，由 Layout 读取）
    try {
      sessionStorage.setItem("kitchen-sentry-upgraded", "1");
    } catch {
      // 忽略 sessionStorage 不可用
    }
  }
  if (version < 4) {
    // 整改闭环实体新增，旧的 risks 可能包含已修改的状态但没有关联的整改任务
    // 保守起见：清空旧 risks（重新从 Mock 加载），清空可能存在的孤儿整改数据
    s.risks = [];
    s.rectificationTasks = [];
    s.auditEvents = [];
    try {
      sessionStorage.setItem("kitchen-sentry-upgraded", "1");
    } catch {
      // 忽略 sessionStorage 不可用
    }
  }
  return s as unknown as AppState;
}

export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      sidebarCollapsed: false,
      toggleSidebar: () => set((s) => ({ sidebarCollapsed: !s.sidebarCollapsed })),

      currentUser: {
        name: "张品控",
        role: "品控主管",
        avatar: "张",
      },
      updateUser: (user) =>
        set((state) => ({ currentUser: { ...state.currentUser, ...user } })),

      risks: [],
      extraInspections: [],
      extraEvidences: [],
      extraStores: [],
      rectificationTasks: [],
      auditEvents: [],

      updateRiskStatus: (riskId, status) => {
        set((state) => ({
          risks: state.risks.map((r) =>
            r.id === riskId ? { ...r, status } : r
          ),
        }));
        toast({
          type: "success",
          title: `风险状态已更新`,
          message: `当前状态：${STATUS_LABEL[status]}`,
          duration: 2500,
        });
      },

      // ============ 整改闭环 ============

      // 确认风险：AI识别 → 待整改，可修改等级和描述
      confirmRisk: (riskId, { level, description }) => {
        const operator = get().currentUser.name;
        const ts = nowLocal();
        set((state) => ({
          risks: state.risks.map((r) =>
            r.id === riskId
              ? {
                  ...r,
                  status: "confirmed" as RiskStatus,
                  ...(level ? { level } : {}),
                  ...(description ? { description } : {}),
                }
              : r
          ),
          auditEvents: [
            ...state.auditEvents,
            {
              id: `evt-${riskId}-${Date.now()}`,
              riskId,
              action: "confirm",
              operator,
              timestamp: ts,
            },
          ],
        }));
        toast({
          type: "success",
          title: "风险已确认",
          message: "已进入待整改状态",
          duration: 2500,
        });
      },

      // 开始整改：待整改 → 整改中，填写责任人和截止日期，创建整改任务
      startRectification: (riskId, { assignee, dueDate }) => {
        const operator = get().currentUser.name;
        const ts = nowLocal();
        const taskId = `task-${riskId}-${Date.now()}`;
        const task: RectificationTask = {
          id: taskId,
          riskId,
          assignee: assignee.trim(),
          dueDate,
          startedAt: ts,
          rejectCount: 0,
        };
        set((state) => ({
          risks: state.risks.map((r) =>
            r.id === riskId
              ? { ...r, status: "fixing" as RiskStatus, rectificationTaskId: taskId }
              : r
          ),
          rectificationTasks: [...state.rectificationTasks, task],
          auditEvents: [
            ...state.auditEvents,
            {
              id: `evt-${riskId}-${Date.now()}`,
              riskId,
              action: "start_fix",
              operator,
              timestamp: ts,
              note: `责任人：${assignee}，截止：${dueDate}`,
            },
          ],
        }));
        toast({
          type: "success",
          title: "整改已启动",
          message: `责任人 ${assignee}，截止 ${dueDate}`,
          duration: 2500,
        });
      },

      // 提交整改：整改中 → 已整改，必须填写说明并添加整改后样本
      submitRectification: (riskId, { fixNote, fixedPhotoUrl }) => {
        const operator = get().currentUser.name;
        const ts = nowLocal();
        // 如果未提供整改后照片，从图库确定性选择一张
        const photoUrl = fixedPhotoUrl || pickFixedPhoto(riskId);
        set((state) => ({
          risks: state.risks.map((r) =>
            r.id === riskId
              ? {
                  ...r,
                  status: "fixed" as RiskStatus,
                  fixNote,
                  fixedPhotoUrl: photoUrl,
                  fixedTime: ts,
                }
              : r
          ),
          rectificationTasks: state.rectificationTasks.map((t) =>
            t.riskId === riskId
              ? { ...t, fixNote, fixedPhotoUrl: photoUrl, submittedAt: ts }
              : t
          ),
          auditEvents: [
            ...state.auditEvents,
            {
              id: `evt-${riskId}-${Date.now()}`,
              riskId,
              action: "submit_fix",
              operator,
              timestamp: ts,
              note: fixNote,
            },
          ],
        }));
        toast({
          type: "success",
          title: "整改已提交",
          message: "等待验证",
          duration: 2500,
        });
      },

      // 验证通过：已整改 → 已验证，记录验证人和时间
      verifyRectification: (riskId) => {
        const operator = get().currentUser.name;
        const ts = nowLocal();
        set((state) => ({
          risks: state.risks.map((r) =>
            r.id === riskId ? { ...r, status: "verified" as RiskStatus } : r
          ),
          rectificationTasks: state.rectificationTasks.map((t) =>
            t.riskId === riskId
              ? { ...t, verifier: operator, verifiedAt: ts }
              : t
          ),
          auditEvents: [
            ...state.auditEvents,
            {
              id: `evt-${riskId}-${Date.now()}`,
              riskId,
              action: "verify",
              operator,
              timestamp: ts,
            },
          ],
        }));
        toast({
          type: "success",
          title: "验证通过",
          message: "整改闭环已完成",
          duration: 2500,
        });
      },

      // 驳回整改：已整改 → 整改中，填写驳回原因，状态退回
      rejectRectification: (riskId, { rejectReason }) => {
        const operator = get().currentUser.name;
        const ts = nowLocal();
        set((state) => ({
          risks: state.risks.map((r) =>
            r.id === riskId
              ? { ...r, status: "fixing" as RiskStatus, fixedPhotoUrl: undefined, fixedTime: undefined, fixNote: undefined }
              : r
          ),
          rectificationTasks: state.rectificationTasks.map((t) =>
            t.riskId === riskId
              ? {
                  ...t,
                  rejectReason,
                  rejectedAt: ts,
                  rejectCount: t.rejectCount + 1,
                  // 重置提交内容，需重新整改
                  fixNote: undefined,
                  fixedPhotoUrl: undefined,
                  submittedAt: undefined,
                }
              : t
          ),
          auditEvents: [
            ...state.auditEvents,
            {
              id: `evt-${riskId}-${Date.now()}`,
              riskId,
              action: "reject",
              operator,
              timestamp: ts,
              note: rejectReason,
            },
          ],
        }));
        toast({
          type: "warning",
          title: "整改已驳回",
          message: "状态退回整改中，请重新整改",
          duration: 3000,
        });
      },

      initRisks: () => {
        const current = get().risks;
        if (current.length === 0) {
          set({ risks: getAllRisks() });
        }
      },

      addInspection: ({ storeId, template, inspector, evidences }) => {
        // 生成巡检 ID（使用本地时间，与展示一致）
        const now = new Date();
        const dateStr = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}`;
        const existing = get().extraInspections;
        const seqNum = existing.length + 1;
        const inspectionId = `INS-${dateStr}-${String(seqNum).padStart(3, "0")}`;

        // 将 evidences 关联到当前巡检 ID
        const evidencesWithInsp = evidences.map((ev) => ({
          ...ev,
          inspectionId,
        }));

        // 基于用户实际取证生成风险
        const risks = generateRisksFromEvidences(inspectionId, template, evidencesWithInsp);

        // 计算得分
        const highCount = risks.filter((r) => r.level === "high").length;
        const midCount = risks.filter((r) => r.level === "mid").length;
        const lowCount = risks.filter((r) => r.level === "low").length;
        const score = Math.max(40, 100 - highCount * 15 - midCount * 8 - lowCount * 3);

        // photoCount 直接由 evidences.length 计算，与照片明细完全同源
        const newInspection: Inspection = {
          id: inspectionId,
          storeId,
          templateId: template.id,
          templateName: template.name,
          inspector,
          // 统一使用本地时间格式，避免 UTC 偏移
          inspectTime: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")} ${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}:${String(now.getSeconds()).padStart(2, "0")}`,
          score,
          grade: calcGrade(score),
          status: "completed",
          riskCount: risks.length,
          highRiskCount: highCount,
          midRiskCount: midCount,
          lowRiskCount: lowCount,
          photoCount: evidencesWithInsp.length,
        };

        set((state) => ({
          extraInspections: [newInspection, ...state.extraInspections],
          extraEvidences: [...evidencesWithInsp, ...state.extraEvidences],
          risks: [...risks, ...state.risks],
        }));

        toast({
          type: "success",
          title: "AI 分析完成",
          message: `已生成巡检 ${inspectionId}，发现 ${risks.length} 项风险`,
          duration: 3000,
        });

        return inspectionId;
      },

      resetData: () => {
        set({
          risks: getAllRisks(),
          extraInspections: [],
          extraEvidences: [],
          extraStores: [],
          rectificationTasks: [],
          auditEvents: [],
        });
        toast({
          type: "info",
          title: "数据已重置",
          message: "所有演示数据已恢复初始状态",
          duration: 2500,
        });
      },

      addStore: ({ name, region, address, manager, phone }) => {
        const existing = get().extraStores;
        const seqNum = existing.length + 1;
        const now = new Date();
        const dateStr = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}`;
        const storeId = `store-new-${dateStr}-${String(seqNum).padStart(3, "0")}`;
        const code = `CXX-N${String(seqNum).padStart(3, "0")}`;
        const openDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;

        const newStore: Store = {
          id: storeId,
          name: name.trim(),
          code,
          address: address.trim(),
          region,
          manager: manager.trim(),
          phone: phone.trim(),
          openDate,
          avgScore: -1, // -1 表示暂无评分，由巡检数据派生
        };

        set((state) => ({
          extraStores: [newStore, ...state.extraStores],
        }));

        toast({
          type: "success",
          title: "门店已创建",
          message: `${newStore.name}（${code}）已加入巡检网络`,
          duration: 3000,
        });

        return storeId;
      },
    }),
    {
      name: "kitchen-sentry-store",
      version: 4,
      // 数据迁移：见 migrateStore 函数
      migrate: migrateStore,
      partialize: (state) => ({
        risks: state.risks,
        extraInspections: state.extraInspections,
        extraEvidences: state.extraEvidences,
        extraStores: state.extraStores,
        rectificationTasks: state.rectificationTasks,
        auditEvents: state.auditEvents,
      }),
    }
  )
);
