import { useState, useEffect, useMemo, useRef } from "react";
import { useNavigate } from "react-router-dom";
import {
  Search, X, LayoutDashboard, ClipboardList, ShieldAlert,
  Store as StoreIcon, Settings, FileText, Sparkles,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { inspections as mockInspections, stores as mockStores, templates } from "@/mock";
import { useStore } from "@/store/useStore";

interface CommandItem {
  id: string;
  title: string;
  subtitle: string;
  icon: typeof Search;
  path: string;
  keywords: string;
  group: "quick" | "page" | "inspection" | "store" | "template";
}

const GROUP_LABELS: Record<CommandItem["group"], string> = {
  quick: "快速操作",
  page: "页面",
  inspection: "巡检",
  store: "门店",
  template: "模板",
};

const GROUP_ORDER: CommandItem["group"][] = [
  "quick",
  "page",
  "inspection",
  "store",
  "template",
];

type RenderRow =
  | { type: "header"; label: string; key: string }
  | { type: "item"; item: CommandItem; index: number; key: string };

export default function CommandPalette() {
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  // 合并 mock + 用户新建数据
  const extraStores = useStore((s) => s.extraStores);
  const extraInspections = useStore((s) => s.extraInspections);

  // 注册快捷键
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setOpen((v) => !v);
      }
      if (e.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // 监听全局打开事件（顶栏搜索提示点击触发）
  useEffect(() => {
    const onOpen = () => setOpen(true);
    window.addEventListener("open-command-palette", onOpen);
    return () => window.removeEventListener("open-command-palette", onOpen);
  }, []);

  useEffect(() => {
    if (open) {
      setQuery("");
      setSelected(0);
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [open]);

  const items = useMemo(() => {
    const allStores = [...extraStores, ...mockStores];
    const allInspections = [...extraInspections, ...mockInspections];
    const storeNameMap = new Map(allStores.map((s) => [s.id, s.name]));

    const quickActions: CommandItem[] = [
      { id: "qa-new", title: "新建 AI 巡检", subtitle: "启动一次新的智能巡检", icon: Sparkles, path: "/inspection/new", keywords: "新建 ai 巡检 new", group: "quick" },
      { id: "qa-risk", title: "查看风险中心", subtitle: "整改闭环管理", icon: ShieldAlert, path: "/risk", keywords: "查看 风险 risk", group: "quick" },
      { id: "qa-inspection", title: "查看巡检记录", subtitle: "巡检记录列表", icon: ClipboardList, path: "/inspection", keywords: "查看 巡检 inspection 记录", group: "quick" },
      { id: "qa-store", title: "门店管理", subtitle: "门店档案列表", icon: StoreIcon, path: "/store", keywords: "门店 store 管理", group: "quick" },
      { id: "qa-settings", title: "系统设置", subtitle: "账号与系统配置", icon: Settings, path: "/settings", keywords: "系统 设置 settings", group: "quick" },
    ];

    const base: CommandItem[] = [
      { id: "nav-dash", title: "工作台", subtitle: "全局数据概览", icon: LayoutDashboard, path: "/", keywords: "dashboard 首页", group: "page" },
      { id: "nav-inspection", title: "巡检管理", subtitle: "巡检记录列表", icon: ClipboardList, path: "/inspection", keywords: "inspection 巡检", group: "page" },
      { id: "nav-risk", title: "风险中心", subtitle: "整改闭环管理", icon: ShieldAlert, path: "/risk", keywords: "risk 风险", group: "page" },
      { id: "nav-store", title: "门店管理", subtitle: `${allStores.length} 家门店档案`, icon: StoreIcon, path: "/store", keywords: "store 门店", group: "page" },
      { id: "nav-settings", title: "系统设置", subtitle: "账号与系统配置", icon: Settings, path: "/settings", keywords: "settings 设置", group: "page" },
    ];

    const fromInspections: CommandItem[] = allInspections.map((i) => {
      const storeName = storeNameMap.get(i.storeId) || "未知门店";
      return {
        id: `insp-${i.id}`,
        title: `${storeName} 巡检`,
        subtitle: `${i.id} · 得分 ${i.score} · ${i.grade}`,
        icon: FileText,
        path: `/inspection/${i.id}`,
        keywords: `${storeName} ${i.id} 巡检`,
        group: "inspection" as const,
      };
    });

    const fromStores: CommandItem[] = allStores.map((s) => ({
      id: `store-${s.id}`,
      title: s.name,
      subtitle: `${s.code} · ${s.region} · 店长 ${s.manager}`,
      icon: StoreIcon,
      path: `/store/${s.id}`,
      keywords: `${s.name} ${s.code} ${s.region} 门店`,
      group: "store",
    }));

    const fromTemplates: CommandItem[] = templates.map((t) => ({
      id: `tpl-${t.id}`,
      title: t.name,
      subtitle: `${t.typeName} · ${t.itemCount} 项检查`,
      icon: ClipboardList,
      path: `/template/${t.id}`,
      keywords: `${t.name} 模板`,
      group: "template",
    }));

    return [...quickActions, ...base, ...fromInspections, ...fromStores, ...fromTemplates];
  }, [extraStores, extraInspections]);

  const filtered = useMemo(() => {
    if (!query.trim()) return items;
    const q = query.toLowerCase();
    return items.filter(
      (it) =>
        it.title.toLowerCase().includes(q) ||
        it.subtitle.toLowerCase().includes(q) ||
        it.keywords.toLowerCase().includes(q)
    );
  }, [items, query]);

  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);

  // 选中项变化时自动滚入视口
  useEffect(() => {
    itemRefs.current[selected]?.scrollIntoView({ block: "nearest" });
  }, [selected, filtered]);

  // 按 group 分组并构建渲染行（含分组标题），保持与 filtered 一致的扁平顺序
  const renderRows = useMemo<RenderRow[]>(() => {
    const map = new Map<CommandItem["group"], CommandItem[]>();
    for (const it of filtered) {
      if (!map.has(it.group)) map.set(it.group, []);
      map.get(it.group)!.push(it);
    }
    const rows: RenderRow[] = [];
    let itemIndex = 0;
    for (const g of GROUP_ORDER) {
      const groupItems = map.get(g);
      if (!groupItems || groupItems.length === 0) continue;
      rows.push({ type: "header", label: GROUP_LABELS[g], key: `header-${g}` });
      for (const item of groupItems) {
        rows.push({ type: "item", item, index: itemIndex, key: item.id });
        itemIndex++;
      }
    }
    return rows;
  }, [filtered]);

  const handleSelect = (item: CommandItem) => {
    navigate(item.path);
    setOpen(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSelected((s) => (s + 1) % filtered.length);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSelected((s) => (s - 1 + filtered.length) % filtered.length);
    } else if (e.key === "Enter") {
      e.preventDefault();
      if (filtered[selected]) handleSelect(filtered[selected]);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-[70] flex items-start justify-center pt-[15vh]">
      {/* 遮罩 */}
      <div
        className="absolute inset-0 bg-ink-900/40 backdrop-blur-sm"
        onClick={() => setOpen(false)}
      />

      {/* 面板 */}
      <div className="relative w-full max-w-[560px] bg-white rounded-2xl shadow-2xl border border-ink-200/80 overflow-hidden animate-fade-in-up">
        {/* 搜索栏 */}
        <div className="flex items-center gap-3 px-4 py-3.5 border-b border-ink-100">
          <Search className="w-5 h-5 text-ink-400" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => { setQuery(e.target.value); setSelected(0); }}
            onKeyDown={handleKeyDown}
            placeholder="搜索页面、巡检、门店、模板..."
            className="flex-1 text-sm bg-transparent outline-none placeholder:text-ink-300 text-ink-800"
          />
          {query && (
            <button
              onClick={() => { setQuery(""); setSelected(0); inputRef.current?.focus(); }}
              className="p-1 rounded-md text-ink-400 hover:bg-ink-100 hover:text-ink-600 transition cursor-pointer"
              aria-label="清空搜索"
            >
              <X className="w-4 h-4" />
            </button>
          )}
          <button
            onClick={() => setOpen(false)}
            className="px-1.5 py-0.5 rounded border border-ink-200 text-[10px] text-ink-400 font-mono hover:bg-ink-50 transition cursor-pointer"
          >
            ESC
          </button>
        </div>

        {/* 结果列表 */}
        <div className="max-h-[320px] overflow-y-auto thin-scroll p-2">
          {filtered.length === 0 ? (
            <div className="py-10 text-center text-ink-400">
              <Sparkles className="w-6 h-6 mx-auto mb-2 opacity-50" />
              <p className="text-sm">未找到匹配结果</p>
              <p className="text-xs mt-1 opacity-70">试试搜索门店名称或巡检编号</p>
            </div>
          ) : (
            <div className="space-y-0.5">
              {renderRows.map((row) => {
                if (row.type === "header") {
                  return (
                    <div
                      key={row.key}
                      className="px-3 pt-2 pb-1 text-[10px] font-semibold uppercase tracking-wider text-ink-400"
                    >
                      {row.label}
                    </div>
                  );
                }
                const { item, index } = row;
                const Icon = item.icon;
                const active = index === selected;
                return (
                  <button
                    key={item.id}
                    ref={(el) => { itemRefs.current[index] = el; }}
                    onClick={() => handleSelect(item)}
                    onMouseEnter={() => setSelected(index)}
                    className={cn(
                      "w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-left transition-all cursor-pointer",
                      active
                        ? "bg-gradient-to-r from-brand-50 to-cyan-50/50 border border-brand-200/60 shadow-sm"
                        : "hover:bg-ink-50/50"
                    )}
                  >
                    <div className={cn(
                      "w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0",
                      active ? "bg-gradient-to-br from-brand-700 to-cyan-600 text-white" : "bg-ink-100/60 text-ink-500"
                    )}>
                      <Icon className="w-4 h-4" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className={cn("text-sm font-medium", active ? "text-brand-700" : "text-ink-800")}>
                        {item.title}
                      </p>
                      <p className="text-[11px] text-ink-400 truncate">{item.subtitle}</p>
                    </div>
                    {active && <span className="text-[10px] text-brand-500 font-medium">↵</span>}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* 底部提示 */}
        <div className="flex items-center justify-between px-4 py-2.5 bg-ink-50/50 border-t border-ink-100 text-[10px] text-ink-400">
          <div className="flex items-center gap-3">
            <span className="flex items-center gap-1"><kbd className="px-1 rounded bg-white border border-ink-200 font-mono">↑↓</kbd> 选择</span>
            <span className="flex items-center gap-1"><kbd className="px-1 rounded bg-white border border-ink-200 font-mono">↵</kbd> 确认</span>
          </div>
          <span>{filtered.length} 个结果</span>
        </div>
      </div>
    </div>
  );
}
