import { useEffect, useState } from "react";
import { CheckCircle2, AlertCircle, X, Info, AlertTriangle } from "lucide-react";
import { cn } from "@/lib/utils";

export type ToastType = "success" | "error" | "info" | "warning";

export interface ToastItem {
  id: string;
  type: ToastType;
  title: string;
  message?: string;
  duration?: number;
}

let toastListeners: ((toasts: ToastItem[]) => void)[] = [];
let toasts: ToastItem[] = [];

function emit() {
  toastListeners.forEach((fn) => fn([...toasts]));
}

export function toast({
  type = "info",
  title,
  message,
  duration = 3000,
}: {
  type?: ToastType;
  title: string;
  message?: string;
  duration?: number;
}) {
  const id = Math.random().toString(36).slice(2, 9);
  const item: ToastItem = { id, type, title, message, duration };
  toasts = [...toasts, item];
  emit();
  if (duration > 0) {
    setTimeout(() => {
      toasts = toasts.filter((t) => t.id !== id);
      emit();
    }, duration);
  }
  return id;
}

export function dismissToast(id: string) {
  toasts = toasts.filter((t) => t.id !== id);
  emit();
}

export function useToasts() {
  const [state, setState] = useState<ToastItem[]>([]);
  useEffect(() => {
    const handler = (t: ToastItem[]) => setState(t);
    toastListeners.push(handler);
    return () => {
      toastListeners = toastListeners.filter((fn) => fn !== handler);
    };
  }, []);
  return state;
}

const ICONS: Record<ToastType, typeof Info> = {
  success: CheckCircle2,
  error: AlertCircle,
  info: Info,
  warning: AlertTriangle,
};

const STYLES: Record<ToastType, string> = {
  success: "bg-emerald-50 border-emerald-200 text-emerald-800",
  error: "bg-red-50 border-red-200 text-red-800",
  info: "bg-brand-50 border-brand-200 text-brand-800",
  warning: "bg-amber-50 border-amber-200 text-amber-800",
};

const ICON_COLORS: Record<ToastType, string> = {
  success: "text-emerald-500",
  error: "text-red-500",
  info: "text-brand-600",
  warning: "text-amber-500",
};

export function ToastContainer() {
  const items = useToasts();
  return (
    <div className="fixed top-20 right-6 z-[60] flex flex-col gap-2.5 pointer-events-none">
      {items.map((item) => {
        const Icon = ICONS[item.type];
        return (
          <div
            key={item.id}
            className={cn(
              "pointer-events-auto w-[320px] rounded-xl border p-4 shadow-elevated backdrop-blur-sm",
              "animate-fade-in-up transition-all duration-300",
              STYLES[item.type]
            )}
          >
            <div className="flex items-start gap-3">
              <Icon className={cn("w-5 h-5 flex-shrink-0 mt-0.5", ICON_COLORS[item.type])} />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold">{item.title}</p>
                {item.message && (
                  <p className="text-xs mt-0.5 opacity-80">{item.message}</p>
                )}
              </div>
              <button
                onClick={() => dismissToast(item.id)}
                className="flex-shrink-0 text-current/50 hover:text-current transition cursor-pointer"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}
