import { lazy, Suspense } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import ErrorBoundary from "@/components/ErrorBoundary";
import Layout from "@/components/Layout";

// 路由级懒加载：按需加载页面，减小首屏 bundle
const Home = lazy(() => import("@/pages/Home"));
const Dashboard = lazy(() => import("@/pages/Dashboard"));
const InspectionList = lazy(() => import("@/pages/InspectionList"));
const InspectionNew = lazy(() => import("@/pages/InspectionNew"));
const InspectionDetail = lazy(() => import("@/pages/InspectionDetail"));
const TemplateList = lazy(() => import("@/pages/TemplateList"));
const TemplateDetail = lazy(() => import("@/pages/TemplateDetail"));
const RiskCenter = lazy(() => import("@/pages/RiskCenter"));
const StoreList = lazy(() => import("@/pages/StoreList"));
const StoreDetail = lazy(() => import("@/pages/StoreDetail"));
const Settings = lazy(() => import("@/pages/Settings"));
const ReportView = lazy(() => import("@/pages/ReportView"));
const NotFound = lazy(() => import("@/pages/NotFound"));

// 懒加载时的兜底 UI
function PageLoading() {
  return (
    <div className="flex items-center justify-center min-h-[50vh]">
      <div className="flex flex-col items-center gap-3">
        <div className="w-10 h-10 rounded-full border-3 border-ink-200 border-t-brand-600 animate-spin" />
        <p className="text-sm text-ink-400">加载中...</p>
      </div>
    </div>
  );
}

export default function App() {
  return (
    <ErrorBoundary>
      <Router>
        <Suspense fallback={<PageLoading />}>
          <Routes>
            <Route element={<Layout />}>
              <Route path="/" element={<Home />} />
              <Route path="/dashboard" element={<Dashboard />} />
              <Route path="/inspection" element={<InspectionList />} />
              <Route path="/inspection/new" element={<InspectionNew />} />
              <Route path="/inspection/:id" element={<InspectionDetail />} />
              <Route path="/template" element={<TemplateList />} />
              <Route path="/template/:id" element={<TemplateDetail />} />
              <Route path="/risk" element={<RiskCenter />} />
              <Route path="/store" element={<StoreList />} />
              <Route path="/store/:id" element={<StoreDetail />} />
              <Route path="/settings" element={<Settings />} />
              <Route path="/report/:id" element={<ReportView />} />
              <Route path="*" element={<NotFound />} />
            </Route>
          </Routes>
        </Suspense>
      </Router>
    </ErrorBoundary>
  );
}
