import { Component, type ReactNode } from "react";

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
}

export default class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  handleReset = () => {
    this.setState({ hasError: false, error: undefined });
  };

  handleReload = () => {
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-ink-50 text-center p-8">
          <div className="w-16 h-16 rounded-2xl bg-red-50 flex items-center justify-center mb-4">
            <svg className="w-8 h-8 text-red-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
              <line x1="12" y1="9" x2="12" y2="13" />
              <line x1="12" y1="17" x2="12.01" y2="17" />
            </svg>
          </div>
          <h1 className="text-xl font-bold text-ink-800 mb-2">应用发生错误</h1>
          <p className="text-sm text-ink-500 max-w-md mb-2">
            页面渲染过程中出现了异常，请尝试重新加载页面
          </p>
          {this.state.error && (
            <pre className="text-xs text-red-500 bg-red-50 rounded-lg p-3 mb-6 max-w-lg overflow-auto">
              {this.state.error.message}
            </pre>
          )}
          <div className="flex items-center gap-3">
            <button
              onClick={this.handleReset}
              className="px-4 py-2 rounded-lg text-sm font-semibold bg-white border border-ink-200 text-ink-700 hover:bg-ink-50 transition cursor-pointer"
            >
              重试
            </button>
            <button
              onClick={this.handleReload}
              className="px-4 py-2 rounded-lg text-sm font-semibold bg-gradient-to-r from-brand-900 to-brand-700 text-white shadow-sm hover:shadow-glow-brand transition cursor-pointer"
            >
              重新加载页面
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}
